# frozen_string_literal: true

# Point existing forum users at their Light Account.
# Posts and groups stay on the same Discourse user.
#
# From the Discourse container, with the map generated by
# web3-app-client/scripts/migrate-to-smart-accounts.mjs:
#
#   FORUM_ADDRESS_MAP=/path/forum-address-map.json \
#     rails runner /path/rewrite_smart_account_users.rb

require "json"

map_path = ENV.fetch("FORUM_ADDRESS_MAP")
map = JSON.parse(File.read(map_path))

map.each do |eoa, smart|
  from = eoa.downcase
  to = smart.downcase

  UserAssociatedAccount.where(provider_name: "siwe").where(
    "lower(provider_uid) = ?",
    from,
  ).find_each do |row|
    row.update!(provider_uid: to)
    puts "siwe #{from} -> #{to} user=#{row.user_id}"
  end

  UserCustomField.where(name: "wallet_address").where(
    "lower(value) = ?",
    from,
  ).update_all(value: to)
end
